#include <stdio.h>
#include <string.h>

static void show_size(int *p) {
    /* Here `p` is a pointer, not an array — sizeof is sizeof(int*) */
    printf("sizeof(p) in callee = %zu\n", sizeof(p));
}

int main(void) {
    int arr[] = {10, 20, 30, 40, 50};
    printf("sizeof(arr) in main = %zu\n", sizeof(arr));   /* 20 (5*4) */
    printf("count = %zu\n", sizeof(arr)/sizeof(arr[0]));  /* 5 */
    show_size(arr);                                       /* 8 (pointer) */
    return 0;
}

#include <stdio.h>

int main(void) {
    int x = 42;
    int *p = &x;            /* p holds the address of x */
    printf("x       = %d\n", x);
    printf("&x      = %p\n", (void*)&x);
    printf("p       = %p\n", (void*)p);
    printf("*p      = %d\n", *p);   /* dereference */
    *p = 99;                          /* modify x through p */
    printf("x now   = %d\n", x);    /* 99 */
    return 0;
}

#include <stdio.h>

int main(void) {
    int arr[5] = {10, 20, 30, 40, 50};
    int *p = arr;             /* points at arr[0] */
    int *q = arr + 3;         /* points at arr[3] */

    printf("p   = %p, *p = %d\n", (void*)p, *p);
    printf("p+1 = %p, *(p+1) = %d\n", (void*)(p+1), *(p+1));
    printf("q - p = %td (ptrdiff_t)\n", q - p);   /* 3 */
    return 0;
}

