static int make_array(int **out, size_t n) {
    int *a = malloc(n * sizeof(int));
    if (!a) return -1;
    for (size_t i = 0; i < n; i++) a[i] = (int)i;
    *out = a;            /* write to caller's pointer */
    return 0;
}

int main(void) {
    int *arr = NULL;
    if (make_array(&arr, 5) == 0) {
        printf("arr[3] = %d\n", arr[3]);   /* 3 */
        free(arr);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *list_push_front(Node *head, int v) {
    Node *n = malloc(sizeof(Node));
    if (!n) return head;
    n->value = v;
    n->next  = head;
    return n;
}

static void list_print(const Node *head) {
    for (const Node *p = head; p; p = p->next) {
        printf("%d -> ", p->value);
    }
    printf("NULL\n");
}

static void list_free(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *h = NULL;
    h = list_push_front(h, 3);
    h = list_push_front(h, 2);
    h = list_push_front(h, 1);
    list_print(h);   /* 1 -> 2 -> 3 -> NULL */
    list_free(h);
    return 0;
}

#include <stdio.h>
#include <pthread.h>
#include <unistd.h>

static void *worker(void *arg) {
    long id = (long)arg;
    printf("thread %ld running\n", id);
    sleep(1);
    printf("thread %ld done\n", id);
    return NULL;
}

int main(void) {
    pthread_t t1, t2;
    pthread_create(&t1, NULL, worker, (void*)1L);
    pthread_create(&t2, NULL, worker, (void*)2L);
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);
    printf("all threads joined\n");
    return 0;
}

#include <stdio.h>
#include <stdatomic.h>
#include <pthread.h>

static atomic_long counter = 0;

static void *worker(void *arg) {
    (void)arg;
    for (int i = 0; i < 100000; i++) {
        atomic_fetch_add(&counter, 1);   /* lock-free atomic increment */
    }
    return NULL;
}

int main(void) {
    pthread_t t[4];
    for (long i = 0; i < 4; i++) pthread_create(&t[i], NULL, worker, NULL);
    for (int i = 0; i < 4; i++) pthread_join(t[i], NULL);
    printf("counter = %ld (expected 400000)\n", counter);
    return 0;
}
